{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Flupirtine, which differs from the query only by the pyridine ring nitrogen (query has CH at that position), showed 90.0% absolute oral bioavailability in healthy volunteers after oral 200 mg versus IV 80 mg, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Safinamide, a fluorobenzylamine-containing drug with a polar amide group, had 95% absolute oral bioavailability in humans, supporting high F for the query's similar benzylamine/fluorophenyl motif, though with lower structural transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tiracizine, which contains an ethyl carbamate on an aromatic amine like the query, had an absolute bioavailability of 0.34 (34%) in patients, still above the 20% threshold and supportive of a positive classification despite lower transferability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is the deaza analogue of flupirtine. Flupirtine has absolute oral bioavailability of 90% in humans, and other structurally related drugs (safinamide, tiracizine) also show F above the 20% threshold. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule; the closest evidence is flupirtine, which differs by one ring nitrogen (pyridine N replaced by CH).",
    "The effect of this pyridine-to-benzene substitution on aqueous solubility, permeability, and first-pass metabolism is not directly quantified.",
    "Lower-similarity supportive evidence (safinamide, tiracizine) is not structurally close enough to independently establish the query's F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

